//! AI enrichment, kept small (docs/ai.md): one CLIP-class model in-process on
//! CPU. From one image embedding we derive text->image search, zero-shot
//! keywords from a configurable vocabulary, zero-shot emojis, and a vibe
//! label. Everything produced here is marked AI-generated by the caller.
//!
//! [`Enricher`] is the seam: [`clip::ClipEnricher`] (feature `clip`) today, an
//! OpenAI-compatible HTTP captioner later, [`mock::MockEnricher`] for tests.

use std::path::{Path, PathBuf};

pub mod mock;
pub mod vocab;
pub mod zeroshot;
#[cfg(feature = "clip")]
pub mod clip;

pub use vocab::Vocabulary;
pub use zeroshot::{Suggestions, ZeroShot};

#[derive(Debug, thiserror::Error)]
pub enum AiError {
    #[error("model files missing or unreadable: {0}")]
    Model(String),
    #[error("inference failed: {0}")]
    Inference(String),
    #[error("vocabulary: {0}")]
    Vocabulary(String),
}

/// Embeddings are L2-normalised; image and text embeddings share one space so
/// cosine similarity (= dot product) compares them.
pub trait Enricher: Send + Sync {
    /// Identifies the embedding space; stored next to every embedding so a model
    /// change triggers re-enrichment.
    fn model_id(&self) -> &str;
    fn dim(&self) -> usize;
    fn embed_image(&self, rgba: &image::RgbaImage) -> Result<Vec<f32>, AiError>;
    fn embed_text(&self, text: &str) -> Result<Vec<f32>, AiError>;
    /// Free-text caption, for backends that can produce one (none in v1).
    fn caption(&self, _rgba: &image::RgbaImage) -> Result<Option<String>, AiError> {
        Ok(None)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum TextEncoderKind {
    /// OpenAI CLIP ViT-B/32 text tower (English).
    #[default]
    Clip,
    /// sentence-transformers/clip-ViT-B-32-multilingual-v1 (DistilBERT +
    /// mean pooling + dense 768->512), aligned to the CLIP image space.
    Multilingual,
}

#[derive(Debug, Clone)]
pub struct ClipOptions {
    /// Layout documented in docs/ai.md.
    pub model_dir: PathBuf,
    pub text_encoder: TextEncoderKind,
    /// `libonnxruntime.so`; None = `ORT_DYLIB_PATH` / system default.
    pub onnxruntime_library: Option<PathBuf>,
    pub threads: usize,
}

/// Dot product of two L2-normalised vectors.
pub fn cosine(a: &[f32], b: &[f32]) -> f32 {
    a.iter().zip(b).map(|(x, y)| x * y).sum()
}

pub fn l2_normalize(v: &mut [f32]) {
    let n = v.iter().map(|x| x * x).sum::<f32>().sqrt();
    if n > 0.0 {
        v.iter_mut().for_each(|x| *x /= n);
    }
}

/// Little-endian f32 blob (database storage format).
pub fn to_blob(v: &[f32]) -> Vec<u8> {
    v.iter().flat_map(|x| x.to_le_bytes()).collect()
}

pub fn from_blob(b: &[u8]) -> Vec<f32> {
    b.chunks_exact(4).map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]])).collect()
}

